def matching_lengths_control(path,libc,base):
    d=controls.dependency;p,blocks,failures=controls.fixture(path,libc,base,'binary')
    d.string(p,d.FIRST,base,b'A'*36,d.G+0x2800);d.string(p,d.SECOND,base,b'B'*6,d.G+0x2C00)
    blocks={d.G+0x2800:37,d.G+0x2C00:7}
    expected=controls.Effects(blocks=blocks,failures=failures)
    returned,memory,watch,wake=d.original(path,libc,base,p,WRAPPER,expected,{})
    actual=controls.Effects(blocks=blocks,failures=failures)
    result=controls.token.apply_token_string_transform_callback(p,wrapper_offset=WRAPPER,argument_block_address=d.PACKED,
        image_base=base,entry_stack_address=controls.SP,allocate=actual.malloc,reallocate=actual.realloc,free=actual.free)
    assert d._read_span(p,d.G,0xA000)==memory and all(d._read_span(p,a,n)==raw for (a,n),raw in watch.items())
    assert actual.calls==expected.calls and actual.blocks==expected.blocks and not wake
    assert result&0xFFFFFFFF==returned&0xFFFFFFFF
    obj=d.DEST;length=int.from_bytes(d._read_span(p,obj+12,4),'little');pointer=int.from_bytes(d._read_span(p,obj+16,8),'little')
    assert length==42 and d._read_span(p,pointer,43)==b'A'*36+b'B'*6+b'\0'
    print('PASS second string pair',hex(base),'length_36_plus_6',flush=True)
    return dict(image_base=hex(base),case='length_36_plus_6',original_hidden_X8_clone_and_append_returned=True,
        complete_wrapper_stream_equal_to_accepted_token_wrapper=True,all_guest_image_and_packed_padding_equal=True,
        ordered_allocator_free_reallocation_effects_equal=True,uint32_append_status_equal=True,
        component_allocator_provider_explicit=True,native_snapshot_input=False,physical_spills_and_PAC_compared=False,
        independently_prepared_first_length=36,independently_prepared_second_length=6,concatenated_length=42)

