    for key in ('snapshots','native_writes','services','pair_arguments','reallocation','next_VM_call','new_allocator_events','protected_ranges'):assert row[key]==EXPECTED[key],key
    assert row['relations']==dict(clone_matches_first=True,append_matches_first_then_second=True,source_bytes_used_only_for_runtime_relational_checks=True)
